<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_enqueue_assets() { wp_enqueue_style( 'sd-style', get_stylesheet_uri(), array(), SD_VERSION ); foreach ( array( 'design-system', 'typography', 'layout', 'header', 'footer', 'components', 'responsive' ) as $style ) { wp_enqueue_style( 'sd-' . $style, SD_URI . '/assets/css/' . $style . '.css', array( 'sd-style' ), SD_VERSION ); } if ( function_exists( 'elementor_theme_do_location' ) || did_action( 'elementor/loaded' ) ) { wp_enqueue_style( 'sd-elementor-compatibility', SD_URI . '/assets/css/elementor-compatibility.css', array( 'sd-style' ), SD_VERSION ); } if ( is_page_template( array( 'page-templates/landing-page.php', 'page-templates/elementor-full-width.php', 'page-templates/community-landing.php', 'page-templates/about-community.php', 'page-templates/contact.php' ) ) ) { wp_enqueue_style( 'sd-landing-pages', SD_URI . '/assets/css/landing-pages.css', array( 'sd-style' ), SD_VERSION ); } foreach ( array( 'navigation', 'sticky-header', 'theme-mode' ) as $script ) { wp_enqueue_script( 'sd-' . $script, SD_URI . '/assets/js/' . $script . '.js', array(), SD_VERSION, true ); } wp_localize_script( 'sd-theme-mode', 'sdTheme', array( 'mode' => sd_get_option( 'sd_dark_mode', 'system' ) ) ); }
add_action( 'wp_enqueue_scripts', 'sd_enqueue_assets' );
